SELECT s.item_id, s.spec_level, s.req_category, s.sys_id, s.doc_no, s.doc_ver, s.approved_dt, l.tgt_id AS traces_to, l.link_type
FROM pd.val_spec_item s LEFT JOIN pd.trace_link l ON l.src_id = s.item_id AND l.link_type='TRACE'
ORDER BY s.spec_level, s.item_id;

SELECT l.src_id AS tc_id, l.tgt_id AS spec_id, tc.method, tc.protocol_id, tc.title
FROM pd.trace_link l JOIN pd.val_test_case tc ON tc.tc_id = l.src_id
WHERE l.link_type='VERIFIES' ORDER BY 2,1;

SELECT cc.cc_no, cc.status, cc.impl_dt, l.link_type, l.tgt_type, l.tgt_id
FROM pd.qms_change_control cc LEFT JOIN pd.trace_link l ON l.src_id = cc.cc_no AND l.src_type='CC'
ORDER BY cc.cc_no;
